import type { Note } from 'app/services/NotesService/types';

import type { GuitarSamples } from './capture';
import {
  POLY_HOP,
  POLY_SAMPLE_RATE,
  POLY_WINDOW,
  createPolyphonicPitchDetector,
} from './polyphonicPitch';
import type { RealtimeNote } from './realtime';

export type RealtimeFrame = {
  events: RealtimeNote[];
  soundingNotes: Note[];
  noteCount: number;
};
const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const noteName = (midi: number) =>
  `${names[midi % 12]}${Math.floor(midi / 12) - 1}` as Note;

// Streaming low-pass/linear resampling keeps a single sample clock across
// arbitrary device blocks, including 44.1 and 96 kHz inputs.
const lowPass = (rate: number, q: number) => {
  const w = (2 * Math.PI * Math.min(4800, rate * 0.4)) / rate;
  const alpha = Math.sin(w) / (2 * q),
    a0 = 1 + alpha;
  const b0 = (1 - Math.cos(w)) / 2 / a0,
    b1 = 2 * b0;
  const a1 = (-2 * Math.cos(w)) / a0,
    a2 = (1 - alpha) / a0;
  let x1 = 0,
    x2 = 0,
    y1 = 0,
    y2 = 0;
  return (x: number) => {
    const y = b0 * x + b1 * x1 + b0 * x2 - a1 * y1 - a2 * y2;
    x2 = x1;
    x1 = x;
    y2 = y1;
    y1 = y;
    return y;
  };
};

export const createPolyphonicStream = (
  onFrame: (frame: RealtimeFrame) => void,
) => {
  const detect = createPolyphonicPitchDetector();
  const ring = new Float32Array(POLY_WINDOW);
  const window = new Float32Array(POLY_WINDOW);
  const active = new Map<
    Note,
    {
      id: number;
      start: number;
      end: number;
      missing?: number;
      missingFrames: number;
    }
  >();
  const candidates = new Map<Note, { start: number; frames: number }>();
  let rate = 0,
    epoch = 0,
    received = 0,
    generated = 0,
    nextSample = 0,
    previous = 0;
  let filter1 = (x: number) => x,
    filter2 = (x: number) => x;
  let nextId = 0,
    finished = false,
    hopEnergy = 0,
    silentHops = 0;
  let soundStart: number | undefined;
  let quietStart: number | undefined;
  let sounding = false;
  const event = (
    note: Note,
    voice: { id: number; start: number; end: number },
  ): RealtimeNote => ({
    id: voice.id,
    startedAt: epoch,
    note: {
      note,
      start: voice.start,
      duration: Math.max(1, voice.end - voice.start),
    },
  });
  const update = (
    notes: Note[],
    center: number,
    end: number,
    silence?: number,
  ) => {
    const events: RealtimeNote[] = [];
    const wasEmpty = !active.size;
    active.forEach((voice, note) => {
      if (notes.includes(note)) {
        voice.missing = undefined;
        voice.missingFrames = 0;
        voice.end = end;
        events.push(event(note, voice));
      } else {
        voice.missing ??= silence ?? center;
        voice.missingFrames++;
        if (silence !== undefined || voice.missingFrames >= 2) {
          voice.end = Math.max(voice.start + 1, voice.missing ?? center);
          events.push(event(note, voice));
          active.delete(note);
        }
      }
    });
    candidates.forEach((_, note) => {
      if (!notes.includes(note)) candidates.delete(note);
    });
    notes.forEach(note => {
      if (active.has(note)) return;
      const recentOnset =
        wasEmpty &&
        soundStart !== undefined &&
        soundStart >= end - (POLY_WINDOW / POLY_SAMPLE_RATE) * 1000;
      const candidate = candidates.get(note) ?? {
        start: recentOnset ? soundStart! : center,
        frames: 0,
      };
      candidate.frames++;
      candidates.set(note, candidate);
      if (candidate.frames < 2) return;
      const voice = {
        id: ++nextId,
        start: candidate.start,
        end,
        missingFrames: 0,
      };
      active.set(note, voice);
      candidates.delete(note);
      events.push(event(note, voice));
    });
    onFrame({
      events,
      soundingNotes: Array.from(active.keys()),
      noteCount: nextId,
    });
  };
  const append = (sample: number) => {
    ring[generated % POLY_WINDOW] = sample;
    generated++;
    hopEnergy += sample * sample;
    if (generated % POLY_HOP === 0) {
      const quiet = Math.sqrt(hopEnergy / POLY_HOP) < 0.006;
      hopEnergy = 0;
      const start = ((generated - POLY_HOP) / POLY_SAMPLE_RATE) * 1000;
      if (quiet) {
        quietStart ??= start;
        silentHops++;
        if (silentHops >= 2 && sounding) {
          sounding = false;
          update([], start, start, quietStart);
        }
      } else {
        if (!sounding) soundStart = start;
        sounding = true;
        silentHops = 0;
        quietStart = undefined;
      }
    }
    if (
      generated < POLY_WINDOW ||
      (generated - POLY_WINDOW) % POLY_HOP !== 0 ||
      !sounding
    )
      return;
    const offset = generated % POLY_WINDOW;
    window.set(ring.subarray(offset));
    window.set(ring.subarray(0, offset), POLY_WINDOW - offset);
    const end = (generated / POLY_SAMPLE_RATE) * 1000;
    const pitches = detect(window);
    const strongest = Math.max(0, ...pitches.map(pitch => pitch.strength));
    // During an existing chord, a new voice needs stronger onset evidence.
    // This rejects short residual partials when another voice is released.
    const notes = pitches
      .filter(pitch => {
        const note = noteName(pitch.midi);
        const lower = pitches.find(other => other.midi === pitch.midi - 12);
        const weakNewOctave =
          lower &&
          active.has(noteName(lower.midi)) &&
          pitch.strength < lower.strength * 0.6;
        return (
          !active.size ||
          active.has(note) ||
          (!weakNewOctave &&
            (candidates.has(note) || pitch.strength >= strongest * 0.32))
        );
      })
      .map(pitch => noteName(pitch.midi));
    update(notes, end - (POLY_WINDOW / 2 / POLY_SAMPLE_RATE) * 1000, end);
  };
  return {
    get noteCount() {
      return nextId;
    },
    push(chunk: GuitarSamples) {
      if (
        finished ||
        !Number.isFinite(chunk.sampleRate) ||
        chunk.sampleRate <= 0
      )
        return;
      if (!rate) {
        rate = chunk.sampleRate;
        epoch = chunk.startedAt;
        filter1 = lowPass(rate, 0.5411961);
        filter2 = lowPass(rate, 1.306563);
      }
      if (chunk.sampleRate !== rate) return;
      for (let i = 0; i < chunk.samples.length; i++) {
        const current = filter2(filter1(chunk.samples[i]));
        while (nextSample <= received) {
          const fraction = received
            ? Math.max(0, Math.min(1, nextSample - received + 1))
            : 1;
          append(previous + (current - previous) * fraction);
          nextSample += rate / POLY_SAMPLE_RATE;
        }
        previous = current;
        received++;
      }
    },
    finish() {
      if (finished) return;
      finished = true;
      const end = quietStart ?? (received / rate) * 1000;
      const events = Array.from(active, ([note, voice]) =>
        event(note, { ...voice, end: voice.missing ?? end }),
      );
      active.clear();
      candidates.clear();
      onFrame({ events, soundingNotes: [], noteCount: nextId });
    },
    dispose() {
      finished = true;
      active.clear();
      candidates.clear();
    },
  };
};
