import type { GuitarSamples } from './capture';
import { createPolyphonicStream } from './polyphonicStream';

type Request = { type: 'samples'; chunk: GuitarSamples } | { type: 'finish' };
const scope = globalThis as unknown as {
  onmessage: (event: MessageEvent<Request>) => void;
  postMessage(message: unknown): void;
};
const stream = createPolyphonicStream(frame =>
  scope.postMessage({ type: 'frame', frame }),
);
scope.onmessage = ({ data }) => {
  try {
    if (data.type === 'samples') {
      stream.push(data.chunk);
      scope.postMessage({ type: 'ack' });
    } else {
      stream.finish();
      scope.postMessage({ type: 'done' });
    }
  } catch {
    scope.postMessage({ type: 'error' });
  }
};
scope.postMessage({ type: 'ready' });
